package net.officefloor.hq.app.person;

import java.util.HashSet;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Gives each selected person the grade, in list order (see PersonRepository#list), through the very steps of the
 * person form's edit, made from the person's current version with their name, terms and contact kept: ApplyPerson (the grade
 * recorded from the from-date), SavePerson and RecordPersonEdited (PERSON_EDITED and the figures it moved). One not on
 * the sheet is skipped.
 */
public class GradePeople {
    public void grade(@PathVariable("sheetId") String sheetId, @Val BulkGradeValues request, PersonRepository people,
            SheetRepository sheets, Rollup rollup, Audit audit, Out<BulkGradeResult> result)
            throws DuplicatePersonNameException, DuplicatePersonContactException, StalePersonException {
        String sheet = sheetId.trim();
        Set<Long> selected = new HashSet<>(request.personIds());
        ApplyPerson apply = new ApplyPerson();
        SavePerson save = new SavePerson();
        RecordPersonEdited record = new RecordPersonEdited();
        int graded = 0;
        for (Person listed : people.list(sheet)) {
            if (!selected.contains(listed.id())) {
                continue;
            }
            Person person = people.find(sheet, listed.id());
            if (person == null) {
                continue;
            }
            PersonValues values = new PersonValues(person.name(), request.grade(), request.by(), person.version(),
                    request.from(), person.terms(), person.contact(), person.tags());
            RollupBefore before = rollup.take(sheet);
            Person[] changed = new Person[1];
            TermsBefore[] terms = new TermsBefore[1];
            ContactBefore[] contact = new ContactBefore[1];
            apply.apply(person, values, sheets, (p) -> changed[0] = p, (t) -> terms[0] = t, (c) -> contact[0] = c);
            save.save(changed[0], values, people);
            record.record(changed[0], values, terms[0], contact[0], before, rollup, audit);
            graded++;
        }
        result.set(new BulkGradeResult(graded));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Objects;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body by the person form's rules: the grade one of A, B or C, the from-date a date or blank; the selected
 *  person ids each once (a missing list is none). */
public class ValidateBulkGrade {
    public void validate(@RequestBody BulkGradeRequest request, Out<BulkGradeValues> values) throws InvalidPersonException {
        if (request == null) {
            throw new InvalidPersonException("A grade is required");
        }
        // validated as the person form would, with a placeholder name
        PersonValues checked = PersonValues.from(new PersonRequest("-", request.grade(), request.by(), null, request.from(), null, null, null));
        List<Long> ids = request.personIds() == null ? List.of()
                : request.personIds().stream().filter(Objects::nonNull).distinct().toList();
        values.set(new BulkGradeValues(ids, checked.grade(), checked.gradeFrom(), checked.by()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes PERSON_EDITED to the audit file once the edit is stored, with terms= at the end when the edit changed the
 * person's own terms (empty when it cleared them), and contact= after it
 * when the edit changed the person's contact (empty when it cleared it). Then writes the
 * figures the change moved (see Rollup). */
public class RecordPersonEdited {
    public void record(@Val Person person, @Val PersonValues values, @Val TermsBefore termsBefore,
            @Val ContactBefore contactBefore, @Val RollupBefore before, Rollup rollup, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + person.sheetId() + " by=" + values.by() + " name=" + person.name()
                + " grade=" + person.grade() + (java.util.Objects.equals(termsBefore.days(), person.terms()) ? ""
                        : " terms=" + (person.terms() == null ? "" : person.terms()))
                + (java.util.Objects.equals(contactBefore.contact(), person.contact()) ? ""
                        : " contact=" + (person.contact() == null ? "" : person.contact())));
        rollup.record(person.sheetId(), values.by(), before);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Applies the edit: the grade is recorded from the from-date (the sheet's today when blank), replacing one recorded
 *  from the same date and keeping the others; a save leaving the grade as the row showed it (in force on the sheet's
 *  today) with the from-date blank records nothing.
 *  The person's own terms become the ones given (null: none), and their contact the one given (null: none), and their tags the ones given. */
public class ApplyPerson {
    public void apply(@Val Person person, @Val PersonValues values, SheetRepository sheets, Out<Person> changed,
            Out<TermsBefore> termsBefore, Out<ContactBefore> contactBefore) {
        termsBefore.set(new TermsBefore(person.terms()));
        contactBefore.set(new ContactBefore(person.contact()));
        changed.set(edited(person, values, sheets.today(person.sheetId())));
    }

    /** The person as the edit leaves them, on the sheet's today (see above). */
    static Person edited(Person person, PersonValues values, LocalDate today) {
        List<PersonGrade> grades = new ArrayList<>(person.grades());
        if (values.gradeFrom() != null || !values.grade().equals(person.grade())) {
            LocalDate from = values.gradeFrom() != null ? values.gradeFrom() : today;
            grades.removeIf((g) -> Objects.equals(g.from(), from));
            grades.add(new PersonGrade(values.grade(), from));
            grades.sort(Comparator.comparing(PersonGrade::from, Comparator.nullsFirst(Comparator.naturalOrder())));
        }
        List<PersonGrade> kept = List.copyOf(grades);
        return new Person(person.id(), person.sheetId(), values.name(), Person.gradeOn(kept, today), person.version() + 1,
                person.retiredFrom(), kept, person.holds(), values.terms(), values.contact(), person.aliases())
                .withRetirements(person.retirements()).withTags(values.tags());
    }
}

